function icon(n){return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.info}</svg>`;}
function hydrateIcons(root=document){$$('[data-icon]',root).forEach(e=>{e.innerHTML=icon(e.dataset.icon);e.removeAttribute('data-icon');});}
function loadFavorites(){try{const favorites=JSON.parse(localStorage.getItem('gather-favorites')||'[]');return Array.isArray(favorites)?favorites:[];}catch{return [];}}
const state={user:null,restaurants:[],cart:{items:[],groups:[],subtotal:0,item_count:0},quote:null,promo:'',q:'',category:'All',openOnly:false,sort:'recommended',address:null,view:'explore',roleTab:'orders',adminTab:'overview',driverTab:'active',dish:null,editCartId:null,orders:[],dashboard:null,currentOrder:null,modalReturnFocus:null,searchTimer:null,poll:null,gpsWatch:null,gpsTimer:null,lastGpsSent:0,latestPosition:null,map:null,mapMarkers:[],rating:5,favorites:loadFavorites()};
async function api(path,opts={}){const response=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts,body:opts.body===undefined?undefined:JSON.stringify(opts.body)});let result={};try{result=await response.json();}catch{}if(!response.ok){if(response.status===401)redirectToSignIn();let detail=result.detail||'We could not complete that action. Please try again.';if(Array.isArray(detail))detail=detail.map(x=>`${(x.loc||[]).filter(p=>p!=='body').join(' ')}: ${x.msg}`).join('; ');const error=new Error(detail);error.status=response.status;throw error;}return result;}
function toast(message,error=false){const e=document.createElement('div');e.className=`app-toast${error?' error':''}`;e.innerHTML=icon(error?'warning':'check')+`<span>${esc(message)}</span>`;$('#toast-region').append(e);setTimeout(()=>e.remove(),5000);}
function errorText(e){return e?.message||'Something went wrong. Please refresh and try again.';}
function status(s){return `<span class="status ${attr(s)}">${esc(title(s))}</span>`;}
function loading(){return '<div class="initial-loading"><span class="spinner-border spinner-border-sm" aria-hidden="true"></span> Just a moment…</div>';}
function empty(heading,message,action='explore',button='Explore restaurants',ic='bag'){return `<div class="empty-state">${icon(ic)}<h3>${esc(heading)}</h3><p>${esc(message)}</p>${action?`<button class="primary-button" data-action="${attr(action)}">${esc(button)} ${icon('arrow-right')}</button>`:''}</div>`;}
function setMain(html){$('#main-content').innerHTML=html;}
const workspaces={restaurant:{icon:'store',label:'Restaurant studio'},driver:{icon:'bike',label:'Driver workspace'},admin:{icon:'chart',label:'Operations'}};
function isCustomer(){return state.user?.role==='customer';}
function redirectToSignIn(){location.replace('/sign-in');}
function homeRoute(){return isCustomer()?'explore':workspaces[state.user?.role]?state.user.role:null;}
function resolveRoute(route){
  if(!isCustomer())return homeRoute();
  return ['explore','orders','reviews'].includes(route)||/^(menu|orders|payment)\/[^/]+$/.test(route)?route:'explore';
}
function currentView(route,userId){return state.user?.id===userId&&resolveRoute(getRoute())===route;}
function resetSessionViews(){
  clearInterval(state.poll);state.poll=null;
  clearTimeout(state.searchTimer);state.searchTimer=null;
  disposeMap();
  Object.assign(state,{restaurants:[],catalogLoaded:false,catalogRequest:null,menu:[],restaurant:null,dish:null,editCartId:null,cart:{items:[],groups:[],subtotal:0,item_count:0},orders:[],dashboard:null,currentOrder:null,searchItems:[],searchQuery:'',q:'',category:'All',sort:'recommended',openOnly:false,roleTab:'orders',adminTab:'overview',driverTab:'active'});
  $('.basket-panel').classList.remove('mobile-open');
  $('#global-search').value='';
}
function updateAccount(){
  const u=state.user,customer=isCustomer(),workspace=workspaces[u?.role];
  $$('[data-customer-only]').forEach(e=>e.hidden=!customer);
  document.body.classList.toggle('workspace-layout',!customer);
  $('.brand').href=customer?'/order':workspace?`/${homeRoute()}`:'/sign-in';
  $('#navigation-label').textContent=customer?'YOUR DAILY GOOD':'YOUR WORKSPACE';
  $('#topbar-context').hidden=customer;
  $('#topbar-context').textContent=workspace?.label||'Gather';
  $('#role-nav').innerHTML=customer?'':workspace?`<a class="nav-link" href="#${attr(u.role)}" data-nav="${attr(u.role)}">${icon(workspace.icon)}${esc(workspace.label)}</a>`:'';
  const footer=$('.mobile-footer');
  footer.hidden=!u;
  footer.innerHTML=customer?`<a href="/order" data-action="explore" aria-label="Order food">${icon('compass')}</a><a href="#orders" aria-label="My orders">${icon('bag')}</a><button data-action="account" aria-label="Account">${icon('user')}</button><button data-action="cart" aria-label="Basket">${icon('cart')}</button>`:workspace?`<a href="#${attr(u.role)}" aria-label="${attr(workspace.label)}">${icon(workspace.icon)}</a><button data-action="account" aria-label="Account">${icon('user')}</button><button data-action="help" aria-label="Help">${icon('help')}</button>`:'';
  $('#account-label').textContent=u?u.name.split(' ')[0]:'Account';
  $('#account-button').setAttribute('aria-label','Your account');
  if(!customer){$('#basket-content').replaceChildren();$('#mobile-cart-count').textContent='0';}
  $('.account-button .avatar').textContent=u?u.name.charAt(0).toUpperCase():'G';
  if(typeof updateDeliveryLabel==='function')updateDeliveryLabel();
}
function showModal(html,{wide=false}={}){state.modalReturnFocus=document.activeElement;$('#modal-content').innerHTML=html;$('#app-modal').classList.toggle('wide-modal',wide);$('#modal-backdrop').hidden=false;$('#app-modal').hidden=false;document.body.style.overflow='hidden';hydrateIcons($('#app-modal'));setTimeout(()=>{const focus=$('input:not([type=hidden]),select,textarea,button:not(.modal-close)', $('#modal-content'));(focus||$('.modal-close')).focus();},40);}
function closeModal(){ $('#app-modal').hidden=true;$('#modal-backdrop').hidden=true;document.body.style.overflow='';state.modalReturnFocus?.focus?.();}
function formError(form,error){let e=$('.form-error',form);if(!e){e=document.createElement('div');e.className='form-error';e.setAttribute('role','alert');form.prepend(e);}e.textContent=errorText(error);e.scrollIntoView({block:'nearest'});}
async function submitTask(form,task){const submit=$('[type=submit]',form);if(submit?.disabled)return;if(submit)submit.disabled=true;$('.form-error',form)?.remove();try{await task();}catch(e){formError(form,e);}finally{if(submit?.isConnected)submit.disabled=false;}}
function go(requested){
  const route=resolveRoute(requested);
  if(!route)return redirectToSignIn();
  if(route==='explore'){
    if(location.pathname!=='/order'||location.hash)history.pushState(null,'','/order');
    routeView();
  }else if(location.hash===`#${route}`)routeView();else location.hash=route;
  $('.sidebar').classList.remove('mobile-open');
}
function requireCustomer(){if(!state.user){redirectToSignIn();return false;}if(!isCustomer()){toast('A customer account is required to order food.',true);return false;}return true;}
function getRoute(){
  if(location.hash)return location.hash.slice(1);
  const parts=location.pathname.split('/').filter(Boolean);
  if(parts[0]==='order'&&parts.length===1)return 'explore';
  if(parts[0]==='restaurants')return parts[1]?'menu/'+parts[1]:'explore';
  return parts.join('/')||homeRoute();
}
async function loadCatalog(){
  if(!isCustomer()||state.catalogLoaded)return;
  if(!state.catalogRequest){
    const userId=state.user.id;
    const request=api('/api/restaurants').then(({restaurants})=>{
      if(!Array.isArray(restaurants))throw new Error('Gather did not receive a restaurant list. Try loading the page again.');
      if(state.catalogRequest===request&&state.user?.id===userId){state.restaurants=restaurants;state.catalogLoaded=true;}
    }).finally(()=>{if(state.catalogRequest===request)state.catalogRequest=null;});
    state.catalogRequest=request;
  }
  await state.catalogRequest;
}
async function routeView(){
  if(!state.sessionReady)return;
  clearInterval(state.poll);state.poll=null;disposeMap();
  const requested=getRoute(),route=resolveRoute(requested),userId=state.user?.id;
  if(!route)return redirectToSignIn();
  if(route!==requested)history.replaceState(null,'',route==='explore'?'/order':'/#'+route);
  state.view=route.split('/')[0];
  $('.sidebar').classList.remove('mobile-open');
  $$('[data-nav]').forEach(e=>{
    const active=e.dataset.nav===state.view||(e.dataset.nav==='explore'&&state.view==='menu');
    e.classList.toggle('active',active);
    if(active)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');
  });
  $('#global-search').value=state.q;
  try{
    if(route==='explore'){
      if(!state.catalogLoaded){setMain(loading());await loadCatalog();}
      if(currentView(route,userId))renderExplore();
      return;
    }
    setMain(loading());
    if(route.startsWith('menu/'))return await renderRestaurant(route.slice(5));
    if(route==='orders')return await renderOrders();
    if(route.startsWith('orders/'))return await renderTracking(route.slice(7));
    if(route==='reviews')return await renderReviews();
    if(route==='restaurant')return await renderRestaurantWorkspace();
    if(route==='driver')return await renderDriverWorkspace();
    if(route==='admin')return await renderAdminWorkspace();
    if(route.startsWith('payment/'))return await renderPayment(route.slice(8));
  }catch(e){if(currentView(route,userId))setMain(empty('A little hiccup',errorText(e),'retry','Try again','warning'));}
}
function cuisineMatch(r){const category=state.category==='Pizza'?'Italian':state.category;return category==='All'||`${r.category} ${(r.tags||[]).join(' ')}`.toLowerCase().includes(category.toLowerCase());}
function renderExplore(){if(!isCustomer()||!state.catalogLoaded)return;state.view='explore';const hour=new Date().getHours();const greeting=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';const displayName=state.user?.role==='customer'?`, ${state.user.name.split(' ')[0]}`:'';let restaurants=state.restaurants.filter(cuisineMatch).filter(r=>!state.openOnly||r.accepting_orders);if(state.q){const query=state.q.toLowerCase();restaurants=restaurants.filter(r=>`${r.name} ${r.category} ${r.description} ${(r.tags||[]).join(' ')}`.toLowerCase().includes(query));}if(state.sort==='rating')restaurants.sort((a,b)=>b.rating-a.rating);if(state.sort==='time')restaurants.sort((a,b)=>a.delivery_minutes-b.delivery_minutes);if(state.sort==='fee')restaurants.sort((a,b)=>a.delivery_fee-b.delivery_fee);const cuisine=[['All','🍽️','All cravings'],['Vietnamese','🍜','Vietnamese'],['Healthy','🥗','Healthy'],['Burgers','🍔','Burgers'],['Japanese','🍣','Japanese'],['Pizza','🍕','Pizza'],['Drinks','🧋','Drinks'],['Korean','🍚','Korean'],['Bakery','🥐','Bakery']];setMain(`
<div class="welcome-line"><div><h1>${esc(greeting+displayName)} <span style="font-size:20px">☀️</span></h1><p>Choose a restaurant menu to start your order.</p></div><div class="date-pill">${icon('pin')} YOUR NEIGHBORHOOD, DELIVERED</div></div>
<label class="mobile-search-box">${icon('search')}<input type="search" id="mobile-search" aria-label="Search restaurants and food" value="${attr(state.q)}" placeholder="What are you craving?"></label><section class="hero" aria-label="Discover local favorites"><div class="hero-copy"><div class="section-eyebrow"><span></span> A LITTLE LOCAL. A LOT TO LOVE.</div><h2>Good food.<br><em>Great company.</em></h2><p>Your neighborhood favorites, brought together in one happy delivery.</p><button class="hero-link" data-action="browse">Browse menus ${icon('arrow-right')}</button></div><span class="hero-spark" aria-hidden="true">✳</span><img class="hero-photo" src="https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=900&auto=format&fit=crop&q=85" alt="A fresh and colorful bowl of vegetables, grains and greens"><div class="hero-small-badge"><span class="badge-leaf">${icon('leaf')}</span><div><strong>Fresh from your neighborhood</strong><small>Good things are closer than you think.</small></div></div></section>
<div class="benefit-strip"><div class="benefit"><span>${icon('layers')}</span>More restaurants. One basket.</div><div class="benefit"><span>${icon('bike')}</span>Good food, right to your door.</div><div class="benefit"><span>${icon('leaf')}</span>Support a little local.</div></div>
<section aria-labelledby="craving-heading"><div class="section-heading"><h2 id="craving-heading">What’s your craving?</h2><button class="text-link" data-action="all-cuisines">Something for everyone ${icon('arrow-right')}</button></div><div class="cuisine-row">${cuisine.map(([v,e,label])=>`<button class="cuisine-chip ${state.category===v?'active':''}" data-action="cuisine" data-category="${v}" aria-pressed="${state.category===v}"><span class="emoji" aria-hidden="true">${e}</span>${label}</button>`).join('')}</div></section>
<section id="restaurants-section" aria-labelledby="restaurants-heading"><div class="section-heading restaurants-heading"><div><h2 id="restaurants-heading">${state.q?'A match for your craving':'Choose a restaurant'}<span class="count-text">${restaurants.length} places</span></h2><p>${state.q?`Results for “${esc(state.q)}”`:'Handpicked local spots. Big on flavor, close to home.'}</p></div><div class="filter-controls"><button class="filter-button ${state.openOnly?'active':''}" data-action="open-only" aria-pressed="${state.openOnly}">${icon('clock')}Open now</button><select class="sort-select" id="restaurant-sort" aria-label="Sort restaurants"><option value="recommended" ${state.sort==='recommended'?'selected':''}>Recommended</option><option value="rating" ${state.sort==='rating'?'selected':''}>Top rated</option><option value="time" ${state.sort==='time'?'selected':''}>Fastest delivery</option><option value="fee" ${state.sort==='fee'?'selected':''}>Delivery fee</option></select></div></div>
${restaurants.length?`<div class="restaurant-grid">${restaurants.map(restaurantCard).join('')}</div>`:empty('No bites found just yet','Try a different food, neighborhood or cuisine to find your next favorite.','clear-filters','Clear filters','search')}
</section><div class="discovery-footer">${icon('leaf')} A good meal starts with a good neighborhood.</div>`);if(state.q&&state.searchQuery===state.q)renderSearchDishes(state.searchItems||[]);}
function restaurantCard(r){const saved=state.favorites.includes(r.id);return `<article class="restaurant-card" tabindex="0" role="link" data-restaurant="${attr(r.id)}" aria-label="View ${attr(r.name)} menu"><div class="restaurant-image"><img src="${attr(safeImage(r.image))}" alt="${attr(r.name)} food" loading="lazy"><span class="restaurant-tag">${icon(r.featured?'leaf':'clock')}${r.featured?'NEIGHBORHOOD FAVORITE':r.accepting_orders?'FRESHLY MADE FOR YOU':'CURRENTLY CLOSED'}</span><button class="favorite-button ${saved?'saved':''}" data-action="favorite" data-id="${attr(r.id)}" aria-label="${saved?'Unsave':'Save'} ${attr(r.name)}" aria-pressed="${saved}">${icon('heart')}</button><span class="image-delivery">${num(r.delivery_minutes)}–${num(Number(r.delivery_minutes)+10)} min</span></div><div class="restaurant-info"><div class="restaurant-title-row"><h3>${esc(r.name)}</h3><span class="rating">${icon('star')}${r.rating==null?'New':Number(r.rating).toFixed(1)} <small>(${num(r.review_count)})</small></span></div><div class="restaurant-categories">${esc(r.category)} <span>·</span> ${esc((r.tags||[]).slice(0,2).join(' · ')||r.description)}</div><div class="restaurant-meta"><span>${icon('clock')}${num(r.delivery_minutes)}–${num(Number(r.delivery_minutes)+10)} min</span><i class="meta-dot"></i><span>${icon('bike')}${r.delivery_fee?money(r.delivery_fee):'Free delivery'}</span><span class="delivery-free">${r.accepting_orders?'Open now':'Closed'}</span></div><div class="restaurant-menu-link" aria-hidden="true">View menu ${icon('arrow-right')}</div></div></article>`;}
async function refreshCart(){if(state.user?.role==='customer'){state.cart=await api('/api/cart');if(state.cart.item_count){try{await refreshQuote();}catch(e){toast(errorText(e),true);}}else state.quote=null;}else{state.cart={items:[],groups:[],subtotal:0,item_count:0};state.quote=null;}renderBasket();}
function deliveryAddressKey(){
  return state.user?.role==='customer' ? 'gather-delivery-address:'+state.user.id : null;
}
function validDeliveryCoordinates(lat,lng){
  return Number.isFinite(lat)&&Math.abs(lat)<=90&&Number.isFinite(lng)&&Math.abs(lng)<=180;
}
function loadDeliveryAddress(){
  state.address=null;
  state.quote=null;
  state.promo='';
  const key=deliveryAddressKey();
  if(!key)return;
  try{
    const saved=JSON.parse(localStorage.getItem(key)||'null');
    if(typeof saved?.address==='string'&&saved.address.trim().length>=5&&saved.address.length<=300&&validDeliveryCoordinates(saved.lat,saved.lng)){
      state.address={address:saved.address,lat:saved.lat,lng:saved.lng,phone:typeof saved.phone==='string'?saved.phone.slice(0,30):''};
    }
  }catch{
    // A stale or inaccessible browser preference must not prevent sign-in.
  }
}
function saveDeliveryAddress(address){
  state.address=address;
  const key=deliveryAddressKey();
  if(key){
    try{localStorage.setItem(key,JSON.stringify(address));}catch{}
  }
}
function updateDeliveryLabel(){
  const label=$('#delivery-label');
  label.textContent=state.address?.address||'Set delivery address';
  label.title=state.address?.address||'';
}
async function refreshQuote(){
  const address=state.address;
  const userId=state.user?.id;
  if(!address||!state.cart.item_count||state.user?.role!=='customer'){
    state.quote=null;
    return null;
  }
  try{
    const quote=await api('/api/cart/quote',{method:'POST',body:{address:address.address,lat:address.lat,lng:address.lng,promo_code:state.promo}});
    if(state.address!==address||state.user?.id!==userId)return null;
    state.quote=quote;
    return quote;
  }catch(e){
    if(state.address===address&&state.user?.id===userId)state.quote=null;
    throw e;
  }
}
function renderBasket(){const c=state.cart;const emptyCart=!c.items.length;$('#mobile-cart-count').textContent=c.item_count||0;$('#basket-content').innerHTML=`<button class="icon-button basket-close" style="display:none" data-action="close-cart" aria-label="Close basket">${icon('x')}</button><div class="basket-title"><h2>Your basket<span style="color:#7f9960">.</span></h2><span class="basket-count">${c.item_count||0} ${(c.item_count||0)===1?'item':'items'}</span></div><button class="basket-delivery" data-action="address" style="width:100%;text-align:left">${icon('bike')}<span><strong>${state.address?esc(state.address.address):'Set delivery address'}</strong><small>${state.address?'Change delivery details':'Add your address to calculate delivery fees.'}</small></span></button>${emptyCart?`<div class="basket-empty"><div class="basket-illustration">${icon('bag')}</div><h3>Good things go in here.</h3><p>Find a dish you love and add it to your basket. Your next good meal is waiting.</p></div><div class="basket-bottom-note">${icon('layers')}<span>Mix your favorites from different restaurants. We’ll take care of the rest.</span></div>`:c.groups.map(g=>`<div class="basket-group"><div class="basket-group-name">${icon('store')}${esc(g.restaurant_name)}</div>${g.items.map(i=>`<div class="basket-item"><img src="${attr(safeImage(i.image))}" alt=""><div class="basket-item-body"><div class="basket-item-title"><span>${esc(i.name)}</span><span>${money(i.line_total)}</span></div><div class="basket-item-options">${esc(optionText(i.options))}${i.note?' · '+esc(i.note):''}</div><div class="basket-item-foot"><div class="quantity-control" aria-label="Quantity for ${attr(i.name)}"><button data-action="cart-qty" data-id="${attr(i.id)}" data-qty="${i.quantity-1}" aria-label="Remove one ${attr(i.name)}">−</button><span>${i.quantity}</span><button data-action="cart-qty" data-id="${attr(i.id)}" data-qty="${i.quantity+1}" aria-label="Add one ${attr(i.name)}">+</button></div><button class="small-text-button" data-action="cart-edit" data-id="${attr(i.id)}">Edit</button></div></div></div>`).join('')}</div>`).join('')}
${!emptyCart?`<form class="promo-entry" id="promo-form">${icon('tag')}<input aria-label="Promo code" name="promo" placeholder="Got a little treat? Add a code" value="${attr(state.promo)}"><button type="submit">Apply</button></form>`:''}<hr class="basket-divider"><div class="basket-totals"><div class="total-row"><span>Subtotal</span><span>${money(c.subtotal)}</span></div><div class="total-row"><span>Delivery fee <span title="Calculated separately for each restaurant">ⓘ</span></span><span>${state.quote?money(state.quote.delivery_fee):emptyCart?'—':state.address?'Calculated at checkout':'Add an address'}</span></div>${state.quote?.discount?`<div class="total-row"><span>Good food savings</span><span style="color:var(--green)">−${money(state.quote.discount)}</span></div>`:''}<div class="total-row grand"><span>${state.quote||emptyCart?'Total':'Before delivery'}</span><span>${money(state.quote?.total??c.subtotal)}</span></div></div><button class="primary-button checkout-button" data-action="checkout" ${emptyCart?'disabled':''}><span>${!emptyCart&&!state.address?'Set delivery address':'Let’s checkout'}</span>${icon('arrow-right')}</button><div class="basket-payment-note">${icon('lock')} A good meal. A secure checkout.</div>${!emptyCart?'<button class="small-text-button" style="display:block;margin:15px auto" data-action="clear-cart">Clear basket</button>':''}`;}
