async function renderRestaurant(id){const userId=state.user?.id;const {restaurant:r,menu}=await api(`/api/restaurants/${encodeURIComponent(id)}`);if(!currentView('menu/'+id,userId))return;state.menu=menu;state.restaurant=r;const categories=[...new Set(menu.map(i=>i.category))];setMain(`<button class="back-button" data-action="explore">${icon('arrow-left')} Back to your neighborhood</button><img class="restaurant-banner" src="${attr(safeImage(r.image))}" alt="${attr(r.name)}"><div class="detail-heading"><div class="section-eyebrow">YOUR NEIGHBORHOOD FAVORITES</div><h1 style="margin-top:8px">${esc(r.name)}</h1><p class="muted" style="font-size:11px">${esc(r.description)}</p><div class="detail-meta"><span>${icon('star')}${r.rating==null?'New':Number(r.rating).toFixed(1)} (${num(r.review_count)} reviews)</span><span>${icon('clock')}${num(r.delivery_minutes)}–${num(r.delivery_minutes+10)} min</span><span>${icon('pin')}${esc(r.address)}</span>${status(r.accepting_orders?'open':'closed')}</div></div>${!r.accepting_orders?'<div class="form-error">This restaurant is taking a break. Please choose another spot for now.</div>':''}${categories.map(cat=>`<h2 class="category-label">${esc(cat)}</h2><div class="menu-grid">${menu.filter(i=>i.category===cat).map(i=>`<button class="menu-card" data-action="dish" data-id="${attr(i.id)}" ${!i.available||!r.accepting_orders?'disabled':''}><div class="menu-card-info"><h3>${esc(i.name)}</h3><div class="menu-description">${esc(i.description)}</div><div class="menu-card-foot"><strong>${money(i.price)}</strong>${i.available?'<span class="add-round">+</span>':'<span class="status">Sold out</span>'}</div></div><img src="${attr(safeImage(i.image))}" alt="${attr(i.name)}" loading="lazy"></button>`).join('')}</div>`).join('')||empty('A fresh menu is on the way','This restaurant is preparing something good. Check back soon.','explore','Explore other restaurants','utensils')}`);}
async function showDish(id,cartId=null){if(!isCustomer())return;const userId=state.user.id;let item=state.menu?.find(i=>i.id===id);if(!item)item=(await api(`/api/menu/${encodeURIComponent(id)}`)).item;if(!isCustomer()||state.user.id!==userId)return;state.dish=item;state.editCartId=cartId;const cartItem=state.cart.items.find(i=>i.id===cartId);const o=cartItem?.options||{};const options=item.options||{};showModal(`<img class="modal-photo" src="${attr(safeImage(item.image))}" alt="${attr(item.name)}"><div class="modal-body-custom"><div class="section-eyebrow">MAKE IT JUST RIGHT</div><h2 id="modal-title" style="margin-top:8px">${esc(item.name)}</h2><p>${esc(item.description)}</p><form id="dish-form"><input type="hidden" name="menu_item_id" value="${attr(item.id)}">${options.sizes?.length?`<div class="form-field"><label class="field-label">Pick your size</label><div class="choice-row">${options.sizes.map((s,n)=>`<label class="option-label"><input type="radio" name="size" value="${attr(s.name)}" ${o.size===s.name||!o.size&&!n?'checked':''}>${esc(s.name)}${s.price?`<small>+${money(s.price)}</small>`:''}</label>`).join('')}</div></div>`:''}${['sugar','ice'].map(key=>options[key]?.length?`<div class="form-field"><label class="field-label" for="dish-${key}">${key==='sugar'?'Sweetness level':'Ice level'}</label><select class="form-select" id="dish-${key}" name="${key}">${options[key].map(s=>`<option ${o[key]===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div>`:'').join('')}${options.toppings?.length?`<div class="form-field"><label class="field-label">A little extra? <span class="muted" style="font-weight:400">Optional</span></label><div class="choice-row">${options.toppings.map(t=>`<label class="option-label"><input type="checkbox" name="toppings" value="${attr(t.name)}" ${(o.toppings||[]).includes(t.name)?'checked':''}>${esc(t.name)} <small>+${money(t.price)}</small></label>`).join('')}</div></div>`:''}<div class="form-field"><label class="field-label" for="dish-note">Anything we should know? <span class="muted" style="font-weight:400">Optional</span></label><textarea class="form-control" name="note" id="dish-note" maxlength="300" rows="2" placeholder="No onions, extra delicious…">${esc(cartItem?.note||'')}</textarea><p class="field-hint">Food allergies? Please contact the restaurant before ordering. Maximum 300 characters.</p></div><div class="modal-actions"><div class="quantity-control"><button type="button" data-action="dish-qty" data-step="-1" aria-label="Decrease quantity">−</button><input type="number" name="quantity" id="dish-quantity" min="1" max="99" value="${cartItem?.quantity||1}" aria-label="Dish quantity" style="width:25px;border:0;background:none;text-align:center;-moz-appearance:textfield"><button type="button" data-action="dish-qty" data-step="1" aria-label="Increase quantity">+</button></div><button type="submit" class="primary-button"><span>${cartId?'Update basket':'Add to basket'}</span><span id="dish-total">${money(item.price)}</span></button></div></form></div>`);updateDishTotal();}
function dishPayload(form){const fd=new FormData(form);return {menu_item_id:state.dish.id,quantity:Number(fd.get('quantity')),note:fd.get('note'),options:{...(fd.get('size')?{size:fd.get('size')}:{}),...(fd.get('sugar')?{sugar:fd.get('sugar')}:{}),...(fd.get('ice')?{ice:fd.get('ice')}:{}),toppings:fd.getAll('toppings')}};}
function updateDishTotal(){const form=$('#dish-form');if(!form||!state.dish)return;const p=dishPayload(form),o=state.dish.options||{};let price=Number(state.dish.price);price+=Number(o.sizes?.find(s=>s.name===p.options.size)?.price||0);for(const t of o.toppings||[])if(p.options.toppings.includes(t.name))price+=Number(t.price);$('#dish-total').textContent=money(price*p.quantity);}
function showAccount(){if(!state.user)return redirectToSignIn();const u=state.user;showModal(`<div class="modal-body-custom"><h2 id="modal-title">Your little corner.</h2><div class="account-detail" style="margin-top:24px"><span class="avatar">${esc(u.name.charAt(0))}</span><div><strong>${esc(u.name)}</strong><p>${esc(u.email)}</p><p>${esc(title(u.role))} account</p></div></div><div class="account-menu">${u.role==='customer'?`<button data-action="account-orders">${icon('bag')}Your orders</button><button data-action="address">${icon('pin')}Delivery details</button>`:`<button data-action="workspace">${icon(u.role==='driver'?'bike':u.role==='restaurant'?'store':'chart')}Open ${esc(u.role)} workspace</button>`}<button data-action="logout">${icon('logout')}Sign out</button></div></div>`);}
